39	/**
40	 * Posts a comment on a live issue. Mentions written as `@handle` in the body
41	 * are resolved against the org's members here, so the stored row and the
42	 * `comment.created` payload agree on who was mentioned — the notification
43	 * fan-out reads that list rather than re-parsing the markdown.
44	 */
45	export async function createComment(
