/**
 * Whether `actor` may see `project` at all. A `private` project is visible
 * only to admins/owners, platform staff, its lead, or an explicit project
 * member; `org` and `public` projects are visible to anyone in the tenant.
 */
export async function canViewProject(
  actor: Actor,
  project: Project,
): Promise<boolean> {
  if (project.visibility !== "private") return true;
  if (actor.orgId !== project.orgId) return false;
  if (actor.isPlatformStaff === true) return true;
  if (actor.role === "admin" || actor.role === "owner") return true;
  if (project.leadId === actor.userId) return true;

  return projectMemberRepo.isProjectMember(
    project.orgId,
    project.id,
    actor.userId,
  );
}

