/** Private projects in `orgId` the actor cannot see; empty for staff/admin/owner. */
async function getInvisibleProjectIds(
  actor: Actor,
  orgId: OrgId,
): Promise<ReadonlySet<ProjectId>> {
  if (
    actor.isPlatformStaff === true ||
    actor.role === "admin" ||
    actor.role === "owner"
  ) {
    return new Set();
  }

  const privateProjects = await projectRepo.listPrivateProjects(orgId);
  const invisible = new Set<ProjectId>();
  for (const project of privateProjects) {
    if (!(await canViewProject(actor, project))) {
      invisible.add(project.id);
    }
  }
  return invisible;
}

