export async function listIssues(
  actor: Actor,
  input: IssueFilterInput,
): Promise<Page<Issue>> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "issue:read", orgResource(input.orgId));

  const page = await issueRepo.listIssues(input);
  const invisibleProjectIds = await getInvisibleProjectIds(actor, input.orgId);

  if (invisibleProjectIds.size === 0) {
    return page;
  }

  const items = page.items.filter(
    (issue) => !invisibleProjectIds.has(issue.projectId),
  );
  const invisibleCount = await issueRepo.countIssuesInProjects(
    input,
    [...invisibleProjectIds],
  );

  return {
    items,
    nextCursor: page.nextCursor,
    total: Math.max(0, page.total - invisibleCount),
  };
}

/** Private projects in `orgId` the actor cannot see; empty for staff/admin/owner. */
async function getInvisibleProjectIds(
  actor: Actor,
  orgId: OrgId,
): Promise<ReadonlySet<ProjectId>> {
  if (
    actor.isPlatformStaff === true ||
    actor.role === "admin" ||
    actor.role === "owner"
  ) {
    return new Set();
  }

  const privateProjects = await projectRepo.listPrivateProjects(orgId);
  const invisible = new Set<ProjectId>();
  for (const project of privateProjects) {
    if (!(await canViewProject(actor, project))) {
      invisible.add(project.id);
    }
  }
  return invisible;
}

